class MyCalendarThree {
    private final TreeMap<Integer,Integer> delta=new TreeMap<>();
    public MyCalendarThree(){
    }
    public int book(int startTime,int endTime){
        delta.put(startTime,delta.getOrDefault(startTime,0)+1);
        delta.put(endTime,delta.getOrDefault(endTime,0)-1);
        int active=0,maximum=0;
        for(int change:delta.values()){
            active+=change;
            maximum=Math.max(maximum,active);
        }
        return maximum;
    }
}

code.kotlin:
class MyCalendarThree {
    private val delta=java.util.TreeMap<Int,Int>();
    fun book(startTime:Int,endTime:Int):Int{
        delta[startTime]=(delta[startTime]?:0)+1;
        delta[endTime]=(delta[endTime]?:0)-1;
        var active=0;
        var maximum=0;
        for(change in delta.values){
            active+=change;
            maximum=maxOf(maximum,active)
        };
        return maximum
    }
}

